mapper.select:
SELECT T2.TYPE_9, T2.TYPE_10, T2.TYPE_11 FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID
AND T1.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG,jdbcType=VARCHAR}

select wfl.PAGE_ID, wfl.BUSINESS_TYPE, wfl.NEXT_USER as curUser, wfl.WORKFLOW_ID processInstanceId, wfl.SEQ_NO as workflowId, wfl.PROCESS_STATE as tradeStatus from SYS_WFL_BUSINESS_LIST wfl where 1=1 and wfl.process_state !='END' and wfl.BUSINESS_TYPE in (select c.menu_id from Tm_App_Audit_Type_Confit c)
and mark.PAGE_ID = #{pageId}
and wfl.SEQ_NO = #{workflowId}
and (wfl.NEXT_USER = #{userName} or wfl.NEXT_USER like '%,${userName},%' or wfl.NEXT_USER like '${userName},%' or wfl.NEXT_USER like '%,${userName}')
order by wfl.update_time desc

(SELECT
DISTINCT SYS_WFL_MODULE.VALUE_DATA userId,
sys_user.real_name userName
FROM
SYS_WFL_MODULE,sys_user ,sys_department pa
WHERE
VALUE_TYPE='user'  and SYS_WFL_MODULE.VALUE_DATA=sys_user.user_name
and pa.dept_code = sys_user.dept_code

    AND pa.INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}


    AND SYS_WFL_MODULE.NODE_ID = #{nodeId,jdbcType=VARCHAR}


    AND SYS_WFL_MODULE.MODULE_ID = #{moduleId,jdbcType=VARCHAR}

) union
(select distinct r.user_id userId,sys_user.real_name userName from sys_user_role r,sys_user  ,sys_department pa where r.user_id=sys_user.user_name
and pa.dept_code = sys_user.dept_code

    AND pa.INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}


and  r.role_id in
(SELECT
VALUE_DATA
FROM
SYS_WFL_MODULE
WHERE
VALUE_TYPE='role'

    AND NODE_ID = #{nodeId,jdbcType=VARCHAR}


    AND MODULE_ID = #{moduleId,jdbcType=VARCHAR}

))

select wfl.NEXT_USER
from  SYS_WFL_BUSINESS_LIST wfl
where wfl.SEQ_NO = #{workFlowId}

select tm.id id, tm.tab_Config_Id tabConfigId, tm.key key, tm.title title, tm.TM_EFFECTFLAG tmEffectflag from Tm_App_Audit_Tab_Detail tm where 1=1
AND tm.TAB_CONFIG_ID = #{tabConfigId}
order by tm.ORDERBY

select token
from TM_APP_TOKEN where 1=1

    AND userid = #{userId}

select bnode.HI_USER userId, bnode.OPINIONS opinions, sys_user.real_name userName, bnode.CREATE_TIME createDate from sys_wfl_business_node bnode,sys_user where 1=1 and bnode.HI_USER=sys_user.user_name
AND bnode.SEQ_NO = #{workflowId}
order by bnode.CREATE_TIME asc

SELECT CUSTOMER_NAME FROM MST_CUSTOMER_INFO
CUSTOMER_TYPE = '01'
AND CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
